import type {WardogsItem} from "./item-library";
type ItemProse = Pick<WardogsItem, "summary" | "description" | "role" | "strengths" | "cautions" | "confirmedFacts" | "unconfirmedFacts">;
type Authored = Omit<ItemProse, "confirmedFacts">;
const p = (summary: string, description: string, role: string, strengths: string[], cautions: string[], unconfirmedFacts?: string[]): Authored => ({summary, description, role, strengths, cautions, unconfirmedFacts});
const authored: Record<string, Authored> = {
  mortar: p("Indirekte Feuerunterstützung gegen Gruppen auf Dächern, Türmen, an FOB-Verteidigungen und bei statischen Zielkämpfen.", "Der Mörser erhielt als erster waffenartiger WARDOGS-Gegenstand eine eigene Seite, weil Aufnahmen tatsächliches Suchinteresse zeigen. Nutze sie als taktischen Leitfaden zu Einsatzbedingungen, Gegenmaßnahmen und Belegen, nicht als endgültige Wertetabelle.", "Setze Meldungen der Teammitglieder in Druck um und zwinge Gegner von vorhersehbaren Positionen weg.", ["Bestraft Gruppen auf Dächern, Türmen und offensichtlichen Zielwegen.", "Kann FOB-Verteidigungen vor dem Angriff von Infanterie oder Fahrzeugen schwächen.", "Belohnt Trupps, die Zielmarkierungen und Korrekturen kommunizieren."], ["Endgültiger Schaden, Nachladezeit, Munitionsgrenzen und Freischaltungen sind unbestätigt.", "Gegner können die Bedienmannschaft angreifen, sobald sie den Abschussort finden.", "Schlechte Informationen machen Schüsse spekulativ statt zuverlässig."]),
  "a-91": p("Die A-91 war in Alpha 1 ein 3.17 kg schweres Gewehr der Assault-XP-Linie mit 5.56x45mm sowie Einzel- und Feuerstoßmodus.", "Die A-91 besetzte in Alpha 1 die Nische kontrollierter Feuerstöße unter den Sturmgewehren. Der Preis wurde nicht erfasst; Kaliber, zwei Feuereinstellungen, Gewicht und Assault-XP-Linie erlauben jedoch einen gezielten Einsatz an Feuerkorridoren, ohne die Balance zum Start vorwegzunehmen.", "Setze auf gezielte Einzelschüsse in der Entfernung und kurze Feuerstöße gegen Ziele auf belebten Wegen. Berücksichtige den unbekannten Kaufpreis, bevor du sie zum Standardgewehr machst.", ["Einzel- und Feuerstoßmodus bieten zwei bewusste Gefechtsrhythmen.", "5.56x45mm gehört zur breitesten erfassten Waffenfamilie.", "Das beobachtete Gewicht von 3.17 kg liegt unter den Alpha-Einträgen für FAL und Galil."], ["Ohne erfassten Alpha-1-Kaufpreis ist kein vollständiger Kostenvergleich möglich.", "Vollautomatik erschien nicht im Eintrag; im Nahkampf sind disziplinierte Feuerstöße nötig.", "STANAG-Magazine wurden separat erfasst, die konkrete A-91-Kompatibilität aber nicht bestätigt."], ["Der Alpha-1-Preis wurde nicht erfasst; Early-Access- und Verkaufspreise der Vollversion sind unbestätigt.", "Schaden, Rückstoß, Aufsatzkompatibilität und Balance können sich im Early Access oder zur Vollversion ändern."]),
  ak74: p("Die AK74 war in Alpha 1 ein 3 kg schweres Assault-XP-Gewehr in 5.45x39mm mit Einzel- und Dauerfeuer.", "Unter den erfassten Alpha-1-Waffen nutzte nur die AK74 5.45x39mm. Diese eigene Munitionsversorgung, der Einzel-/Dauerfeuer-Wahlschalter und 3 kg Gewicht kennzeichnen ihren Vorabstand, obwohl der Händlerpreis nicht erfasst wurde.", "Spare Munition mit Einzelfeuer und schalte bei nahen Vorstößen auf Dauerfeuer. Die AK74 bindet die Ausrüstung an die weniger gemeinsam genutzte Versorgung mit 5.45x39mm.", ["Einzel- und Dauerfeuer decken dosierte Schüsse und unmittelbaren Nahkampfdruck ab.", "3 kg waren in Alpha 1 leichter als die anderen erfassten Sturmgewehre.", "Eine erfasste AK74-Trommel mit 75 Schuss liefert einen konkreten Kontext für hohe Kapazität."], ["Der Händlerpreis wurde in Alpha 1 nicht erfasst.", "Nur eine erfasste Waffe nutzte 5.45x39mm; Munition lässt sich weniger breit teilen als 5.56x45mm.", "Preis, Handhabungskosten und endgültige Verfügbarkeit der 75-Schuss-Trommel wurden nicht erfasst."], ["Der Alpha-1-Preis wurde nicht erfasst; Early-Access- und Verkaufspreise der Vollversion sind unbestätigt.", "Trommelpreis, endgültiger Rückstoß, Schaden und Fortschrittsabstimmung sind für Early Access und Vollversion unbestätigt."]),
  "amp-9": p("Die AMP-9 war in Alpha 1 eine $900 teure Medic-XP-MP in 9x19mm mit Einzel-/Dauerfeuer und beobachteten 1.4 kg.", "Die AMP-9 verband das geringste erfasste Gewicht einer Schusswaffe dieser 14 Modelle mit einer Medic-XP-Anforderung und vier dokumentierten Magazingrößen. Der Alpha-1-Stand zeigt eine mobile Unterstützungswaffe; Gesamtkosten hängen von Magazinwahl und 9x19mm ab, nicht nur vom Grundpreis $900.", "Nutze sie als leichte Hauptwaffe für die Nahverteidigung des Sanitäters: Einzelfeuer spart 9x19mm, Dauerfeuer hilft unter unmittelbarem Druck bei Wiederbelebungen und Zielen.", ["1.4 kg in Alpha 1 lassen mehr Raum für Medizin und Schutz.", "Einzel-/Dauerfeuer erlauben Unterstützungsspielern Sparsamkeit oder Nahkampffeuer.", "Beobachtete AMP-9-Magazine mit 15, 20, 30 und 50 Schuss bieten mehrere Kapazitätsbudgets."], ["$900 in Alpha 1 enthalten keine Munition oder Ersatzmagazine.", "Das beobachtete 50-Schuss-Magazin kostete $180, ein deutlicher Aufpreis zur günstigen MP.", "Reichweitenleistung, Rückstoß und Schadensabfall wurden nicht erfasst."], ["Schaden, Rückstoß, Reichweitenverhalten und Medic-XP-Anforderungen können sich für Early Access oder Vollversion ändern.", "Alpha-1-Magazinpreise und Kompatibilität sind nicht als endgültige Werte bestätigt."]),
  "amr-50": p("Die AMR 50 war in Alpha 1 ein $8,800 teures Recon-XP-Scharfschützengewehr in .50 Cal mit Repetiermechanismus, Magazin und 12.5 kg.", "Die AMR 50 lag am äußersten Ende der erfassten Waffenökonomie: teuerstes und schwerstes dieser 14 Modelle. .50 Cal war außerdem mit $50 pro Schuss und $250 pro Schachtel gelistet. Jeder Einsatz bedeutete in Alpha 1 eine spezialisierte Recon-Investition.", "Setze sie von vorbereiteten Beobachtungspositionen ein, wo Ersatzpreis, 12.5 kg und teure Munition durch Ziele gerechtfertigt sind, die ein leichteres Gewehr weniger sicher bewältigt.", [".50 Cal verleiht dem Modell eine eigene Rolle als schweres Gewehr im Alpha-Katalog.", "Repetiermechanismus und Magazin erlauben gezielte Folgeschüsse ohne Einzelpatronen-Nachladung.", "Ein erfasstes AMR-50-Magazin mit 10 Schuss kostete $30 und bietet eine konkrete Kapazitätswahl."], ["$8,800 in Alpha 1 setzen einen großen Teil des angesparten Guthabens aufs Spiel.", "12.5 kg sind deutlich schwerer als BMR-308 und Sturmgewehre.", ".50 Cal hatte mit $50 den höchsten erfassten Preis je Patrone vor endgültiger Balance."], ["Infanterieschaden, Rüstungswirkung, Zielschwankungen und Handhabung können sich für Early Access oder Vollversion ändern.", "$8,800 und .50-Cal-Kosten sind Alpha-1-Beobachtungen, keine bestätigte endgültige Wirtschaft."]),
  "bmr-308": p("Die BMR-308 war in Alpha 1 ein $6,000 teures halbautomatisches Recon-XP-Präzisionsgewehr in .308 Winchester mit 3.9 kg.", "Die BMR-308 bot Recon in Alpha 1 einen halbautomatischen Mittelweg zwischen der massiven AMR 50 und dem ungewöhnlichen Compound Bow. .308 Winchester verband sie mit FAL und einem gemeinsamen 20-Schuss-Magazineintrag; endgültige Kompatibilität darf daraus nicht angenommen werden.", "Nutze wiederholtes Präzisionsfeuer auf mittleren und langen Sichtlinien, reserviere Geld für .308 Winchester und vermeide Munitionsverbrauch im Nahkampf wie bei einem Sturmgewehr.", ["Halbautomatik erlaubt schnellere Korrekturen als der beobachtete Repetiermechanismus der AMR 50.", "3.9 kg in Alpha 1 waren neben dem 12.5-kg-Scharfschützeneintrag handhabbar.", "Für die FAL/BMR-308-Familie wurde ein 20-Schuss-Magazin zu $150 erfasst."], ["$6,000 in Alpha 1 machen den Verlust teuer.", "Standard-.308-Winchester wurde mit $4 je Schuss und $40 je Schachtel beobachtet.", "Optikpassung, Magazinhandhabung, Schaden und effektive Reichweite wurden nicht als finale Spezifikation erfasst."], ["Optikkompatibilität, Rückstoß, Schaden und Reichweitenabstimmung sind für Early Access und Vollversion unbestätigt.", "Der beobachtete Alpha-Preis $6,000 und Magazinkosten können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "bushmaster-m17s": p("Die Bushmaster M17S erschien in Alpha 1 zu $0 als 3.17-kg-Assault-XP-Gewehr in 5.56x45mm mit Einzel- und Feuerstoßmodus.", "Die M17S teilte den erfassten 5.56x45mm-, Einzel-/Feuerstoß- und 3.17-kg-Stand von A-91 und KH-2002, doch ihr Händler zeigte $0. Das ist eine Alpha-1-Beobachtung, kein Beweis für eine dauerhaft kostenlose Waffe zum Start.", "Behandle M17S als kontrollierte Feuerstoßoption der Alpha-Belege. Nutze $0 nur im historischen Kostenvergleich, bis spätere Builds ihren Erwerb bestätigen.", ["Das angezeigte $0 reduzierte den erfassten Grundwaffenpreis auf null.", "Einzel- und Feuerstoßmodus ermöglichen dosiertes Feuer statt zwingenden Vollautomatikverbrauchs.", "5.56x45mm gehörte zur am breitesten vertretenen Munitionsfamilie."], ["$0 im Vorab-Händler kann Startzugang, Platzhalter oder zeitweilige Abstimmung bedeuten.", "Vollautomatik wurde nicht erfasst.", "Separate STANAG-Einträge beweisen nicht, dass jede Kapazität zur M17S passt."], ["Der angezeigte Alpha-1-Preis $0 ist nicht für Early Access oder Vollversion bestätigt.", "Erwerbsregeln, Schaden, Rückstoß und Aufsatzkompatibilität können sich für Early Access oder Vollversion ändern."]),
  "compound-bow": p("Der Compound Bow war in Alpha 1 eine $800 teure Recon-XP-Waffe mit 1.3 kg, Standardpfeilen und Ziehen-und-Loslassen.", "Der Compound Bow war das leichteste erfasste Modell und die einzige Waffe mit Standardpfeilen und Zug-/Loslassrhythmus. $800 in Alpha 1 waren neben Recon-Gewehren günstig, aber Pfeilschaden, Rückgewinnung, Geschwindigkeit und Kapazität wurden nicht erfasst.", "Wähle den leichten Recon-Bogen, wenn du Zug und Auslösung timen kannst. Trage eine Seitenwaffe für Situationen, in denen ein normales Magazin mehr Fehler verzeiht.", ["1.3 kg waren das geringste Gewicht der 14 erfassten Waffenmodelle.", "$800 in Alpha 1 lagen deutlich unter BMR-308 und AMR 50.", "Standardpfeile sind eine eigene Versorgungswahl außerhalb der Schusswaffenkaliber."], ["Ziehen und Loslassen bot keine beobachtete halb- oder vollautomatische Alternative.", "Pfeilschaden, Geschwindigkeit, Fall, Rückgewinnung und Tragmenge wurden nicht erfasst.", "Der Katalog enthält keine eigene Pfeilroute oder bestätigte Aufsatzmatrix."], ["Pfeilschaden, Geschwindigkeit, Rückgewinnung und Kapazität sind für Early Access und Vollversion unbestätigt.", "$800 in Alpha und Recon-XP-Anforderungen können vom aktuellen Early Access oder der Vollversion abweichen."]),
  deagle: p("Die Deagle war in Alpha 1 eine halbautomatische .50-AE-Seitenwaffe zu $900; Gewicht und Fortschritt wurden nicht erfasst.", "Die Deagle hatte mit $900 einen Hauptwaffenpreis unter den Alpha-1-Seitenwaffen und verwendete das seltene .50 AE. Ein Siebenschussmagazin wurde für $50 erfasst; fehlendes Gewicht und Fortschritt lassen wichtige Ausrüstungsfragen offen.", "Wähle sie, wenn eine teure halbautomatische Reserve geringer Kapazität zum Plan passt. Rechne .50 AE und Magazine ein, bevor du günstigere Seitenwaffen vergleichst.", [".50 AE war unter den 14 erfassten Waffenmodellen einzigartig.", "Halbautomatik vermeidet langsamere Zug-/Loslass- oder Repetierzyklen von Spezialwaffen.", "Ein konkretes Siebenschussmagazin liefert dokumentierten Kapazitätskontext."], ["$900 in Alpha 1 entsprachen der AMP-9 ohne Munition und Magazine.", "Das Siebenschussmagazin zu $50 begrenzt die Fehlertoleranz.", "Saison 1 bestätigt Career 85; aktuelles Gewicht und vollständige Traglast bleiben ungeprüft."], ["Alpha 1 ließ Gewicht und Fortschritt offen. Saison 1 bestätigt Career 85, das Gewicht für Early Access und Vollversion bleibt ungeprüft.", "Schaden, Rückstoß und Magazinverhalten können vom aktuellen Build abweichen; $900 im Alpha-1-Händler sind für Early Access ungeprüft."]),
  fal: p("Die FAL war in Alpha 1 ein $5,500 teures Assault-XP-Gewehr in .308 Winchester mit Einzel-/Dauerfeuer und 4.25 kg.", "Die FAL war das schwerste und teuerste erfasste Sturmgewehr. Sie tauschte die verbreitete 5.56x45mm-Versorgung gegen .308 Winchester und Vollautomatik; auch ihre erfassten 20- und 30-Schuss-Magazine waren teurer als viele Kleinkalibermagazine.", "Spare .308 Winchester mit Einzelfeuer und nutze Dauerfeuer nur für kurzen, entscheidenden Druck. Gewehr, Munition und Magazine erforderten in Alpha 1 erhebliche Ausgaben.", ["Einzel- und Dauerfeuer erlauben präzise Schüsse oder Nahkampfdruck.", ".308 Winchester unterscheidet sie von leichteren 5.56x45mm-Sturmgewehren.", "Erfasste 20- und 30-Schuss-Magazine geben zwei konkrete Kapazitätsoptionen."], ["$5,500 in Alpha 1 lagen weit über Galil und AMP-9.", "4.25 kg waren das höchste erfasste Sturmgewehrgewicht.", "Ein FAL-Magazin mit 30 Schuss kostete $250, normale .308-Patronen je $4."], ["Schaden, Rückstoß, Vollautomatikkontrolle und Assault-XP-Anforderungen können sich im Early Access oder zur Vollversion ändern.", "$5,500 und erfasste Magazinkosten sind Alpha-1-Beobachtungen, keine bestätigten Werte der Vollversion."]),
  galil: p("Die Galil war in Alpha 1 ein $2,200 teures, 3.95 kg schweres Assault-XP-Gewehr in 5.56x45mm mit Einzel-/Dauerfeuer.", "Die Galil besetzte die mittlere Alpha-1-Preislage: teurer und schwerer als die erfassten 5.56x45mm-Feuerstoßgewehre, aber günstiger als die .308-FAL und mit Vollautomatik. Eigene 35- und 50-Schuss-Magazine ergänzen ihren Kapazitätskontext.", "Nutze die Galil als vielseitiges Sturmgewehr: dosiertes Einzelfeuer auf offenem Gelände und Dauerfeuer, wenn der Trupp Distanz schließt oder eine verteidigte Stellung räumt.", ["Einzel-/Dauerfeuer unterstützen Munitionssparsamkeit und Nahkampfdruck.", "Der Alpha-Katalog erfasste eigene Galil-Magazine mit 35 und 50 Schuss.", "$2,200 in Alpha 1 lagen deutlich unter der FAL, bei weiterhin vorhandenem Dauerfeuer."], ["3.95 kg waren schwerer als A-91, AK74, M17S und KH-2002.", "Das 50-Schuss-Magazin kostete in Alpha 1 $110 ohne Munition.", "Rückstoß, Nachladezeit, Schaden und Aufsatzeffekte wurden nicht als finale Werte erfasst."], ["Rückstoß, Schaden, Aufsatzpassung und Assault-XP-Abstimmung sind für Early Access und Vollversion unbestätigt.", "Gewehr- und Magazinpreise aus Alpha 1 können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "ggx-17": p("Die GGX 17 war in Alpha 1 eine halbautomatische 9x19mm-Seitenwaffe; Preis, Gewicht und Fortschritt wurden nicht erfasst.", "Die GGX 17 bildete die konventionelle halbautomatische Hälfte des erfassten GGX-Paares. 9x19mm verbindet sie mit der günstigsten beobachteten Munitionsschachtel, doch drei fehlende Händlerfelder verhindern einen belastbaren Kosten- oder Traglastvergleich.", "Nutze die GGX 17 als dosierte 9x19mm-Reserve. Sie ersetzt nicht die beobachtete Vollautomatik der GGX 18; lasse Budget frei, bis ein späterer Build ihren Erwerbspreis bestätigt.", ["Halbautomatik fördert kontrollierte Reserveschüsse und sparsamen Munitionsverbrauch.", "Normale 9x19mm-Patronen wurden zu $1 einzeln und $10 pro Schachtel beobachtet.", "Das gemeinsame Kaliber kann die Versorgung neben AMP-9 und GGX 18 vereinfachen."], ["Preis, Gewicht und Fortschritt fehlten vollständig im Alpha-1-Eintrag.", "GGX-Magazine mit 33 und 50 Schuss wurden erfasst, die modellbezogene Passung jedoch nicht bewiesen.", "Schaden, Rückstoß, Kapazität und Handhabung waren nicht Teil des Waffeneintrags."], ["Preis, Gewicht und Fortschritt wurden in Alpha 1 nicht erfasst und bleiben für Early Access und Vollversion unbestätigt.", "Magazinpassung, Schaden, Rückstoß und Kapazität können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "ggx-18": p("Die GGX 18 war in Alpha 1 eine 9x19mm-Seitenwaffe mit Einzel-/Dauerfeuer; Preis, Gewicht und Fortschritt wurden nicht erfasst.", "Die GGX 18 unterschied sich durch die beobachtete Vollautomatik von GGX 17 und gab den Alpha-1-Seitenwaffen eine kompakte automatische Option. Der Modus ist dokumentiert, doch fehlende Preise, Gewichte, Fortschritt und Magazinpassung erlauben keine Aussage zum Wert beim Start.", "Bleibe im normalen Reserveeinsatz bei Einzelfeuer. Nutze Dauerfeuer für dringenden Nahkampfdruck, wenn rascher 9x19mm-Verbrauch den Verlust an Munitionskontrolle rechtfertigt.", ["Einzel-/Dauerfeuer machen sie zur flexibleren erfassten GGX-Seitenwaffe.", "9x19mm hatte niedrige beobachtete Standardkosten von $1 je Patrone und $10 je Schachtel.", "Das gemeinsame Kaliber passt zu einem Versorgungskonzept mit Schwerpunkt AMP-9."], ["Der Alpha-1-Eintrag erfasste weder Preis noch Gewicht oder Fortschritt.", "Vollautomatik kann ein Seitenwaffenmagazin trotz günstiger Munition schnell leeren.", "GGX-Einträge für 33 Schuss zu $70 und 50-Schuss-Trommeln zu $110 beweisen keine finale GGX-18-Passung."], ["Preis, Gewicht und Fortschritt wurden in Alpha 1 nicht erfasst und bleiben für Early Access und Vollversion unbestätigt.", "Vollautomatikabstimmung, Magazinpassung, Rückstoß und Schaden können vom aktuellen Early Access oder der Vollversion abweichen."]),
  judge: p("Die Judge war in Alpha 1 eine .45-Colt-Seitenwaffe zu $250; Feuermodus, Gewicht und Fortschritt wurden nicht erfasst.", "Die Judge hatte mit $250 den niedrigsten erfassten Waffenpreis oberhalb null und verwendete als einziges Modell .45 Colt. Der Munitionskatalog zeigte eine $33-Schachtel, doch ohne Feuermodus, Gewicht und Fortschritt ist ihr Verhalten unsicherer als der Preis.", "Prüfe die Judge als Seitenwaffe mit niedrigen Grundkosten, deren Kampfrhythmus noch im Spiel zu bestätigen ist. Rechne die vergleichsweise teure .45-Colt-Schachtel in Ersatzkäufe ein.", ["$250 in Alpha 1 waren der niedrigste erfasste positive Waffenpreis dieser Modelle.", ".45 Colt gibt ihr eine eigene Identität in der Seitenwaffenversorgung.", "Eine .45-Colt-Schachtel zu $33 wurde beobachtet; ein Teil der Ersatzkosten ist dokumentiert."], ["Feuermodus, Gewicht und Fortschritt fehlten im Alpha-1-Waffeneintrag.", "Für die Judge war kein eigenes Magazin oder Kapazitätseintrag verfügbar.", "$250 Grundpreis belegen weder Schaden, Nachladetempo, Reichweite noch endgültigen Wert."], ["Feuermodus, Gewicht und Fortschritt wurden in Alpha 1 nicht erfasst und bleiben für Early Access und Vollversion unbestätigt.", "Kapazität, Nachladeverhalten, Schaden und $250 Alpha-Preis können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "kh-2002": p("Die KH-2002 war in Alpha 1 ein 3.17 kg schweres Assault-XP-Gewehr in 5.56x45mm mit Einzel-/Feuerstoßmodus; der Preis wurde nicht erfasst.", "Die KH-2002 vervollständigte das erfasste Trio aus 3.17 kg schweren 5.56x45mm-Feuerstoßgewehren. Anders als die M17S mit angezeigten $0 hatte sie keinen erfassten Alpha-1-Preis. Überlappende Eckdaten reduzieren die Modellwahl deshalb nicht auf Kosten.", "Nutze kontrolliertes Sturmfeuer: Einzelschüsse auf längeren Feuerkorridoren und Feuerstöße bei kurzen Sichtfenstern. Spätere Build-Belege müssen Kosten und Handhabungsunterschiede noch klären.", ["Einzel- und Feuerstoßmodus bieten zwei kontrollierte Muster für den Munitionsverbrauch.", "3.17 kg in Alpha 1 waren leichter als Galil und FAL.", "5.56x45mm war das am breitesten geteilte erfasste Kaliber und bietet mehr gemeinsamen Versorgungskontext."], ["Der Kaufpreis in Alpha 1 wurde nicht erfasst.", "Der beobachtete Eintrag zeigt keine Handhabungsunterschiede zu A-91 oder M17S.", "STANAG-Kapazitäten und Optiken wurden erfasst, KH-2002-Kompatibilität aber nicht bestätigt."], ["Der Alpha-1-Preis wurde nicht erfasst; Early-Access- und Verkaufspreise der Vollversion sind unbestätigt.", "Modellspezifische Handhabung, Schaden, Rückstoß und Aufsatzpassung können sich für Early Access und Vollversion ändern."]),
  "ah-6m-miniguns": p("Die AH-6M Miniguns erschien in Alpha 1 als Kampfhubschrauber zu $7,000; ihre Erwerbsbedingung war unlesbar.", "Die AH-6M Miniguns ist das bewaffnete Mitglied der leichten AH-6-Familie im Alpha-1-Händler. Die Kampfhubschrauberrolle und $7,000 unterscheiden sie vom Transport-MH-6. Unlesbare Voraussetzungen und fehlendes Waffenverhalten begrenzen den Eintrag auf eine Rollenerklärung statt endgültiger Leistungsdaten.", "Nutze die AH-6M für kurze Angriffsüberflüge und schone sie zwischen Gefechten. Jeder Ersatz belastet die beobachtete Alpha-Ökonomie.", ["$7,000 in Alpha 1 lagen unter AH-6R Rockets und Havoc.", "Die Kampfhubschrauberrolle unterscheidet sie vom frei käuflichen MH-6-Transporter.", "Die Bezeichnung Miniguns liefert einen klaren Vergleichsgrund zur raketenbewaffneten AH-6R."], ["Die Alpha-1-Erwerbsbedingung war unlesbar; Verfügbarkeit folgt nicht allein aus dem Preis.", "Minigunschaden, Munition, Konvergenz und effektive Reichweite wurden nicht erfasst.", "Widerstandsfähigkeit, Besatzung, Handhabung und Gegenmaßnahmen bleiben unbekannt."], ["Die unlesbare Alpha-1-Bedingung bleibt für Early Access und Vollversion unbestätigt.", "Minigunleistung, Flugverhalten, Widerstandsfähigkeit und $7,000 Alpha-Preis können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "ah-6r-rockets": p("Die AH-6R Rockets wurde in Alpha 1 als Raketenhubschrauber zu $12,500 mit unlesbarer Erwerbsbedingung gelistet.", "Die AH-6R Rockets ersetzt die Minigun-Ausrichtung der leichten Familie durch eine Raketenrolle und einen deutlich höheren erfassten Preis. $12,500 in Alpha 1 verlangen eine bewusstere Kaufentscheidung als bei AH-6M; Raketenlast, Explosion, Nachladen und Freigabebedingung waren aber nicht hinreichend lesbar.", "Reserviere die AH-6R für geplante Luftangriffsfenster mit wertvollen bestätigten Zielen und gesichertem Abflug. Ein teurer Hubschrauber braucht Unterstützung durch den Trupp.", ["Die Raketenhubschrauberbezeichnung kennzeichnet eine andere Angriffsrolle als AH-6M Miniguns.", "Die beobachtete Familienbezeichnung macht AH-6M zum direkten Preis- und Rollenvergleich.", "$12,500 in Alpha 1 lagen unter Havoc bei weiterhin spezialisiertem Kampfeinsatz."], ["Die Erwerbsbedingung war im Alpha-1-Material unlesbar.", "Raketenanzahl, Flächenschaden, Genauigkeit und Nachversorgung wurden nicht erfasst.", "Der hohe beobachtete Ersatzpreis erhöht das Risiko ungestützter Angriffsläufe."], ["Die unlesbare Alpha-1-Bedingung bleibt für Early Access und Vollversion unbestätigt.", "Raketenlast, Schaden, Nachversorgung, Flugverhalten und Preis können vom aktuellen Early Access oder der Vollversion abweichen."]),
  bobcat: p("Der Bobcat war im Alpha-1-Fahrzeughändler ein frei käuflicher leichter Transporter zu $500.", "Der Bobcat besetzte das untere Preisende des erfassten Fahrzeugkatalogs. Leichter Transport und beobachteter freier Kauf machen ihn zur klarsten Alpha-1-Referenz für einfache Mobilität. Sitze, Laderaum, Schutz, Tempo und Fortbestand dieses Zugangs in späteren Builds sind jedoch nicht belegt.", "Kaufe den Bobcat für kurze Stellungswechsel und Rückholfahrten mit wenig Kapitalbindung, wenn Bewegung wichtiger ist als Waffen, Schutz oder Fracht.", ["$500 waren der niedrigste beobachtete Preis unter den 20 erfassten Fahrzeugmodellen.", "Freier Kauf war in Alpha 1 sichtbar, ohne angezeigte Fortschrittslinie.", "Die Rolle als leichter Transporter richtet die Entscheidung auf Bewegung statt Kampfausrüstung."], ["Freier Kauf wurde nur in Alpha 1 beobachtet und ist kein endgültiges Zugangsversprechen.", "Sitzanzahl, Stauraum, Tempo, Widerstandsfähigkeit und Geländeverhalten wurden nicht erfasst.", "Ein niedriger Händlerpreis belegt keine geringe Belastung durch Kraftstoff, Reparatur oder Ersatz."], ["Freier Kauf und $500 sind Alpha-1-Beobachtungen, keine bestätigten Regeln für Early Access oder Vollversion.", "Kapazität, Schutz, Handhabung, Stauraum und Betriebskosten bleiben für Early Access und Vollversion unbestätigt."]),
  "dune-buggy": p("Der Dune Buggy erschien in Alpha 1 als schneller Transporter zu $1,500 ab Driver 10.", "Der Dune Buggy war der ausdrücklich auf Geschwindigkeit ausgerichtete Bodentransporter des erfassten Katalogs. Driver 10 und $1,500 in Alpha 1 liegen über Bobcats Einstiegsmobilität. Schnell ist dabei eine Händlerrolle, kein Beweis für endgültiges Höchsttempo, Beschleunigung, Haftung oder Unfallsicherheit.", "Wähle den Dune Buggy für schnelle Aufklärung und Routenwechsel, wenn Ankunftszeit wichtiger ist als Schutz. Plane keine ungeprüfte Passagier- oder Frachtkapazität ein.", ["Schneller Transport war die ausdrückliche Alpha-1-Rollenbezeichnung.", "$1,500 lagen unter den größeren Kodiak- und Humvee-Familien.", "Driver 10 war eine lesbare Fortschrittsanforderung statt einer unbekannten Bedingung."], ["Endgültiges Tempo, Beschleunigung, Bodenhaftung und Überschlagverhalten wurden nicht erfasst.", "Saison 1 nennt Driver 8; Driver 10 aus Alpha 1 ist historisch.", "Schutz, Sitzanzahl und Frachtkapazität wurden nicht aufgezeichnet."], ["Saison 1 nennt eine Freischaltung der Driver-Linie zu $25,000; $1,500 Alpha-1-Fahrzeugpreis bleiben für Early Access ungeprüft.", "Tempo, Handhabung, Widerstandsfähigkeit, Sitze und Frachtverhalten können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "flakpanzer-gepard": p("Der Flakpanzer Gepard wurde in Alpha 1 als Flugabwehrpanzer zu $8,000 ab Wardog 45 gelistet.", "Der Flakpanzer Gepard ist das spezialisierte gepanzerte Flugabwehrmodell der erfassten Liste. Die Wardog-Voraussetzung und ein Preis unter L2A6 und SPH-2 unterstützen die Rolle gegen Luftziele. Erkennung, Geschützverhalten, Panzerung, Besatzung und Abdeckungsbereich sind jedoch keine dokumentierten endgültigen Systeme.", "Schütze wertvolle Bodenmittel und wahrscheinliche Flugrouten mit dem Gepard. Halte Bodenunterstützung bereit, denn Flugabwehr bedeutet keine Sicherheit vor jeder Bedrohung.", ["Gepanzerte Flugabwehr war eine einzigartige Rolle unter den 20 beobachteten Fahrzeugen.", "$8,000 in Alpha 1 waren günstiger als beide anderen schweren Wardog-Fahrzeuge.", "Wardog 45 gab im erfassten Händler ein lesbares Fortschrittsziel."], ["Erkennungsreichweite, Munition, Geschützschaden, Höhenwinkel und Zielverfolgung wurden nicht erfasst.", "Die Flugabwehrrolle belegt keinen Schutz vor Panzern, Artillerie oder Infanterie.", "Wardog 45 und $8,000 sind ausschließlich Vorabbeobachtungen."], ["Wardog 45 und $8,000 bleiben für Early Access und Vollversion unbestätigt.", "Panzerung, Flugzielerkennung, Waffenleistung, Besatzung und Munition können vom aktuellen Early Access oder der Vollversion abweichen."]),
  havoc: p("$18,000 für Havoc gelten nur für Alpha; ein Saison-1-Pilotenbericht nennt höhere Kosten mit Ausrüstung und starke Flugabwehrkonter.", "Havoc stand am oberen Ende der beobachteten Fahrzeugpreise und trug die allgemeine Kampfhubschrauberrolle statt einer waffenspezifischen AH-6-Bezeichnung. Es war die größte wirtschaftliche Luftinvestition des Alpha-1-Standes. Bewaffnung, Panzerung, Besatzungsanordnung und Zugangsbedingung fehlen für einen endgültigen Vergleich.", "Investiere in Havoc, wenn das Team den wertvollen Kampfhubschrauber mit Zielinformationen, Luftraumüberblick und einer Abflugroute außerhalb konzentrierten Gegenfeuers unterstützen kann.", ["Angriffshubschrauber war die ausdrückliche Alpha-1-Rolle, getrennt von Transportfluggeräten.", "$18,000 kennzeichnen im beobachteten Händler die deutlichste Luftinvestition.", "Die Rolle bietet einen Vergleichspunkt zu den günstigeren Angriffsvarianten AH-6M und AH-6R."], ["Die Erwerbsbedingung war unlesbar; der Zugangsweg wurde nicht erfasst.", "Waffen, Panzerung, Sensoren, Gegenmaßnahmen und Besatzung wurden nicht aufgezeichnet.", "Neuere Pilotenangaben zu Kosten und Freischaltung stammen von einem Spieler, nicht einer offiziellen Preisliste.", "Koordinierte Flugabwehr kann ein wertvolles Fluggerät ausschalten; prüfe die Route vor dem Kauf."], ["Die unlesbare Alpha-1-Bedingung bleibt für Early Access und Vollversion unbestätigt.", "Ein Saison-1-Pilot meldete am 20. September Pilot 35 und ungefähr $22,000–$30,000 für einen ausgerüsteten Einsatz; diese Community-Beobachtung ist ungeprüft.", "Bewaffnung, Panzerung, Besatzungsanordnung, Flugmodell, Gegenmaßnahmen und aktueller Preis benötigen Prüfung im aktuellen Client."]),
  "humvee-m249": p("Der Humvee M249 verband in Alpha 1 bewaffneten Transport, $3,750 Kaufpreis und Driver 25.", "Der Humvee M249 ergänzt die geschützte Humvee-Plattform um eine benannte Unterstützungswaffe unterhalb des erfassten Minigun-Preises. Driver 25 lag viel später als beim Kodiak M249. Beide bewaffneten Transporter zu $3,750 waren damit verschiedene Fortschrittsentscheidungen, obwohl Waffenleistung und Lafettendetails fehlen.", "Bewege ein kleines Team und gebe einem Passagier oder Schützen eine defensive Feuerrolle. Plane Routen unabhängig vom unbestätigten Schutz der Lafette oder Kabine.", ["Die beobachtete bewaffnete Transportrolle verbindet Bewegung mit einer benannten M249-Lafette.", "$3,750 in Alpha 1 lagen $750 über dem unbewaffneten Humvee und unter der Minigun-Version.", "Driver 25 unterschied den Fortschritt klar vom Kodiak M249 ab Driver 8."], ["M249-Munition, Schwenkbereich, Schutz, Genauigkeit und Schützenexposition wurden nicht erfasst.", "Driver 25 ist eine Alpha-1-Beobachtung, keine finale Freischaltanforderung.", "Sitzanzahl, Kabinenschutz, Frachtkapazität und Reparaturverhalten bleiben unbekannt."], ["Driver 25 und $3,750 bleiben für Early Access und Vollversion unbestätigt.", "M249-Verhalten, Schutz, Sitze, Frachtkapazität und Handhabung können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "humvee-minigun": p("Der Humvee Minigun war in Alpha 1 ein schwerer bewaffneter Transporter zu $4,500 mit unlesbarer Händlerbedingung.", "Der Humvee Minigun war der teuerste erfasste Humvee und als einziger schwerer bewaffneter Transporter bezeichnet. $1,500 mehr als das Grundmodell zeigen eine eigene Alpha-1-Preisstufe. Unlesbarer Zugang und fehlende Waffendaten verhindern Aussagen zu Feuerrate, Versorgung, Panzerung oder Wert gegenüber M249.", "Behandle ihn als mobile Plattform für schweres Feuer mit geschützter Route, abgestimmtem Schützen und Rückzugsplan. Seine Frontpanzerung ist nicht nachgewiesen.", ["Schwerer bewaffneter Transport war eine eigene beobachtete Rolle der Humvee-Familie.", "Der Minigun-Name trennt die Waffenausrichtung von der günstigeren M249-Variante.", "$4,500 in Alpha 1 lagen unter dem größeren bewaffneten Ural Defender M249."], ["Die Alpha-1-Bedingung war unlesbar; sein Zugangsweg bleibt unbekannt.", "Minigun-Munition, Anlaufverhalten, Schwenkbereich, Schaden und Schützenexposition wurden nicht erfasst.", "Die schwere bewaffnete Transportrolle bestätigt keinen Schutz wie bei einem Panzer."], ["Die unlesbare Alpha-1-Bedingung bleibt für Early Access und Vollversion unbestätigt.", "Minigunleistung, Fahrzeugschutz, Kapazität, Handhabung und Preis können vom aktuellen Early Access oder der Vollversion abweichen."]),
  humvee: p("Der normale Humvee war im Alpha-1-Händler ein geschützter Transporter zu $3,000 ab Driver 15.", "Der unbewaffnete Humvee definierte in Alpha 1 den geschützten Transport seiner Familie. Er kostete so viel wie der frachtorientierte Kodiak Pickup und weniger als beide bewaffneten Humvees. Geschützt bleibt eine Klassenbezeichnung: Panzerungsschwelle, Sitzanordnung, Stauraum und Überlebensvergleich wurden nicht erfasst.", "Nutze den normalen Humvee für geschützten Personentransport und Stellungswechsel auf umkämpften Straßen, wenn eine Lafette weniger wichtig ist als der niedrigere beobachtete Kaufpreis.", ["Geschützter Transport war seine ausdrückliche Alpha-1-Rolle, keine abgeleitete Panzerungsbehauptung.", "$3,000 lagen unter beiden bewaffneten Humvee-Varianten.", "Driver 15 ordnete ihn auf der erfassten Driver-Linie zwischen Dune Buggy und Humvee M249 ein."], ["Panzerungswert, Schadensmodell, Sitzanzahl und Frachtgrenze wurden nicht erfasst.", "Geschützter Transport garantiert keine Sicherheit vor Minen, schweren Waffen oder Hinterhalten.", "Driver 15 und $3,000 können sich nach Alpha 1 ändern."], ["Driver 15 und $3,000 bleiben für Early Access und Vollversion unbestätigt.", "Schutz, Sitze, Stauraum, Mobilität, Kraftstoff und Reparaturen können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "kodiak-m249": p("Der Kodiak M249 war in Alpha 1 ein bewaffneter Transporter zu $3,750 ab Driver 8.", "Der Kodiak M249 war der früheste bewaffnete Transporter mit lesbarer Driver-Bedingung im erfassten Katalog. Preis und Rolle entsprachen Humvee M249, der aber Driver 25 statt 8 benötigte. Fahrgestellwahl und Fortschrittszeitpunkt sind daher getrennte Fragen, noch bevor die fehlenden Fahr-, Schutz- und Lafettendaten hinzukommen.", "Wähle Kodiak M249 für mobile Waffenunterstützung früh auf der Driver-Linie, ohne zur geschützten Ural-Defender-Familie aufzusteigen. Die Fahrgestellleistung bleibt ungeprüft.", ["Driver 8 war die niedrigste beobachtete Stufenbedingung unter bewaffneten Bodenfahrzeugen.", "Die bewaffnete Transportrolle verbindet die Kodiak-Nutzfahrzeugfamilie mit einer benannten M249-Lafette.", "$3,750 in Alpha 1 entsprachen dem später freigeschalteten Humvee M249 und erlauben einen direkten Fortschrittsvergleich."], ["Waffenmunition, Schwenkbereich, Schutz und Schützenexposition wurden nicht erfasst.", "Driver 8 beweist keine dauerhaft frühe Freischaltung.", "Sitze, Frachteinbußen, Handhabung, Widerstandsfähigkeit und Reparaturkosten wurden nicht aufgezeichnet."], ["Driver 8 und $3,750 bleiben für Early Access und Vollversion unbestätigt.", "M249-Verhalten, Sitze, Fracht, Schutz, Handhabung und Widerstandsfähigkeit können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "kodiak-pickup": p("Der Kodiak Pickup wurde in Alpha 1 als Frachttransporter zu $3,000 hinter einer Freischaltung zu $15,000 gelistet.", "Der Kodiak Pickup ist das einzige erfasste Fahrzeug mit ausdrücklicher Frachttransportrolle. Der Händler zeigte $3,000 Kaufpreis und separat $15,000 Freischaltung: zweistufige Alpha-1-Kosten statt einer Stufenbedingung. Ladevolumen, Beladungsregeln und Dauerhaftigkeit der Freischaltung wurden nicht erfasst.", "Nutze den Kodiak Pickup für Versorgungsfahrten, wenn die Frachtrolle wichtiger ist als der niedrigere beobachtete Preis des normalen Kodiak oder die M249-Lafette.", ["Frachttransport war eine einzigartige Rolle der beobachteten Fahrzeugliste.", "$3,000 Alpha-1-Kaufpreis entsprachen dem normalen Humvee bei anderem Logistikzweck.", "Die separate Freischaltung zu $15,000 war lesbar; die vollständigen beobachteten Einstiegskosten lassen sich benennen."], ["Die Aufzeichnung erklärt nicht, ob $15,000 dauerhaft, wiederholt oder kontogebunden galten.", "Frachtplätze, Beladungsinteraktion, Gegenstandsbeschränkungen und Verlustverhalten wurden nicht erfasst.", "Schutz, Sitze, Tempo, Geländeverhalten und Kraftstoff wurden nicht aufgezeichnet."], ["$15,000 Freischaltung und $3,000 Kaufpreis bleiben für Early Access und Vollversion unbestätigt.", "Freischaltungsdauer, Frachtregeln, Kapazität, Sitze, Schutz und Handhabung können vom aktuellen Early Access oder der Vollversion abweichen."]),
  kodiak: p("Der normale Kodiak erschien in Alpha 1 als frei käuflicher Nutztransporter zu $2,500.", "Der normale Kodiak lag im beobachteten Händler zwischen Bobcat und spezialisierten Kodiak-Varianten. Nutztransportrolle und freier Kauf machen ihn zum allgemeinen Alpha-1-Einstieg der Familie. Was Nutzen konkret bedeutet — Passagierraum, Stauraum, Abschleppen oder Gelände — lässt der Eintrag offen.", "Nutze Kodiak für allgemeine Bewegung, wenn der Trupp weder die ausdrückliche Frachtrolle des Pickup noch die M249-Lafette braucht. Prüfe die praktische Kapazität im aktiven Build.", ["Freier Kauf wurde in Alpha 1 ohne angezeigte Driver- oder Geldfreischaltung beobachtet.", "$2,500 waren günstiger als beide spezialisierten Kodiak-Varianten.", "Nutztransport gibt ihm eine breitere beobachtete Rolle als dem schnellen Dune Buggy."], ["Freier Kauf war ein Alpha-1-Zustand und muss nicht fortbestehen.", "Die Nutzrolle nennt keine Sitze, Fracht, Abschleppfunktion, Schutz- oder Geländeleistung.", "Unterschiede zum Pickup außer Rolle und Preis wurden nicht erfasst."], ["Freier Kauf und $2,500 sind keine bestätigten Regeln für Early Access oder Vollversion.", "Sitze, Fracht, Abschleppen, Schutz, Handhabung, Kraftstoff und Reparaturen bleiben für Early Access und Vollversion unbestätigt."]),
  l2a6: p("Der L2A6 war im Alpha-1-Katalog der Kampfpanzer zu $14,000 ab Wardog 35.", "Der L2A6 trug die einzige Kampfpanzerbezeichnung der Liste und den zweithöchsten erfassten Fahrzeugpreis. Wardog 35 lag vor Gepard und SPH-2. Der Alpha-1-Eintrag zeigte aber weder Panzerungszonen noch Bewaffnung, Besatzungsplätze, Munition, Mobilität oder nötige Unterstützung für den Betrieb.", "Setze den L2A6 als vom Team gestütztes schweres Druckmittel auf offenen Feuerkorridoren ein. Infanterieaufklärung und Logistik bleiben nötig, denn die Kampfpanzerrolle beseitigt kein Stellungsrisiko.", ["Kampfpanzer war eine einzigartige beobachtete Klasse im Katalog mit 20 Modellen.", "Wardog 35 war die früheste lesbare Bedingung der drei Panzerungs- und Artillerieeinträge.", "$14,000 in Alpha 1 trennten ihn klar von Transport und leichterem Flugabwehrpanzer."], ["Panzerungswerte, Schwachpunkte, Waffen, Munition, Besatzungszahl und Reparatursysteme wurden nicht erfasst.", "Die Kampfpanzerrolle beweist keine Immunität gegen Infanterie, Luftfahrzeuge oder Artillerie.", "Wardog 35 und $14,000 Kaufpreis sind keine finalen Fortschritts- oder Wirtschaftsaussagen."], ["Wardog 35 und $14,000 bleiben für Early Access und Vollversion unbestätigt.", "Panzerung, Bewaffnung, Munition, Besatzungsrollen, Mobilität, Kraftstoff und Reparaturen können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "mh-6": p("Der MH-6 war in Alpha 1 ein frei käuflicher leichter Lufttransporter zu $6,250.", "Der MH-6 war der günstigste Hubschrauber des erfassten Katalogs und das einzige Fluggerät mit Transportrolle und beobachtetem freiem Kauf. Er liefert den zivilen Rollenvergleich zur AH-6-Familie. Passagierplätze, Landeverhalten, Zuladung, Überlebensfähigkeit und Pilotanforderungen außerhalb der Händlerbedingung fehlen.", "Nutze MH-6 für leichte Luftlandung, Abholung und schnelle Stellungswechsel, wenn Transport wichtiger ist als benannte Bordwaffen. Wähle Landezonen und Rückwege vorsichtig.", ["$6,250 in Alpha 1 waren der niedrigste beobachtete Fluggerätepreis.", "Freier Kauf war im Händler sichtbar statt einer unlesbaren oder stufengebundenen Voraussetzung.", "Leichter Lufttransport gibt ihm eine eigene Mobilitätsrolle neben bewaffneten AH-6-Varianten."], ["Freier Kauf wurde nur in Alpha 1 beobachtet und verspricht keine endgültige Verfügbarkeit.", "Sitzanzahl, Passagierexposition, Flugverhalten, Widerstandsfähigkeit und Landetoleranz wurden nicht erfasst.", "Die Transportrolle belegt weder Frachtfähigkeit noch eine endgültig unbewaffnete Ausstattung."], ["Freier Kauf und $6,250 sind keine bestätigten Regeln für Early Access oder Vollversion.", "Sitze, Ausstattung, Flugverhalten, Widerstandsfähigkeit, Fracht und Pilotanforderungen bleiben für Early Access und Vollversion unbestätigt."]),
  "sph-2": p("Saison 1 verschob Artillery Tank auf Career 90 mit $500,000 Freischaltung; SPH-2-Händlerpreise und Besatzungsabläufe bleiben Build-Beobachtungen.", "SPH-2 war das einzige Selbstfahrlafettenmodell des erfassten Händlers und benötigte Wardog 55. Spätere Closed-Beta-Aufnahmen zeigten drei Besatzungspositionen, Stabilisierung, indirekte Entfernungseinstellung, 155-mm-Munition und manuelles Nachladen. Alpha zeigte $10,000 Kaufpreis; ein späterer Autorenleitfaden $8,000 Wiederholungskauf nach separaten $400,000 Freischaltung. Dieser Widerspruch bleibt als Build-Beleg erhalten statt zu einem Endpreis vereinheitlicht zu werden.", "Setze SPH-2 als abgestimmtes Mittel für indirektes Feuer mit Zielinformationen, geschützter Feuerstellung und Logistik ein. Wechsle die Stellung, sobald sie vorhersehbar wird.", ["Stabilisierung hält das Visierbild für wiederholte Korrekturen beim indirekten Feuer nutzbar.", "Beobachtete Besatzungsplätze trennen Fahren, das 155-mm-Hauptgeschütz und obere Deckung.", "Richtig ausgeführte manuelle Nachladeeingaben können die Verzögerung verkürzen."], ["Der Fahrer kann beim Fahren nicht schießen; allein musst du anhalten und den Sitz wechseln.", "Eine vorhersehbare Feuerstellung ist anfällig für Drohnen, Luftfahrzeuge, Gegenbatteriefeuer und jagende Infanterie.", "Saison 1 bestätigt die Artillery-Tank-Kategoriebedingung, keinen aktuellen SPH-2-Händlerpreis; prüfe Preis, Reichweite und Granatenwerte im aktuellen Build."], ["$10,000 Alpha-Kauf und $8,000 späterer Beta-Wiederholungskauf widersprechen sich; keiner ist für Early Access bestätigt.", "Ein Saison-1-Spieler meldet $8,000 Wiederholungskauf und $11,000–$13,000 ausgerüsteten Einsatz; im aktuellen Händler ist das nicht unabhängig geprüft.", "Das offizielle Änderungsprotokoll nennt Artillery Tank statt SPH-2; aktuelle Modellidentität und Wiederholungspreis brauchen Prüfung im aktuellen Client.", "Reichweite, Explosion, Panzerung und Munitionskosten brauchen Prüfung im aktuellen Client."]),
  "uh-1y-miniguns": p("Die UH-1Y Miniguns war in Alpha 1 ein bewaffneter Mehrzweckhubschrauber zu $8,000 mit unlesbarer Bedingung.", "UH-1Y Miniguns ergänzt die größere UH-1Y-Familie um bewaffneten Mehrzweckeinsatz, nur $600 über dem erfassten normalen Transporter. Gerade diese geringe Alpha-1-Differenz macht die unlesbare Bedingung wichtig: ohne Zugang, Waffen-, Sitz- und Zuladungsdaten ist die bewaffnete Variante kein durchweg besserer Transporter.", "Nutze UH-1Y Miniguns für begleitete Luftlandungen und Abholrouten mit möglichem Bord-Deckungsfeuer. Bewahre den Transportauftrag, statt ungeprüfter Waffenleistung nachzugehen.", ["Bewaffneter Mehrzweckhubschrauber verbindet eine Transportfamilie mit benannter Bewaffnung.", "$8,000 lagen nur $600 über dem normalen UH-1Y.", "Das Familienpaar ermöglicht einen klaren Vergleich bewaffneten Einsatzes mit Transport beim Kauf."], ["Die Alpha-1-Bedingung war unlesbar; der Zugang ist nicht direkt mit der Pilot-Bedingung des Grundmodells vergleichbar.", "Minigunanzahl, Feuerwinkel, Munition, Schaden und Schützenexposition wurden nicht erfasst.", "Passagierkapazität, Fracht, Widerstandsfähigkeit und Handhabungsunterschiede bleiben unbekannt."], ["Die unlesbare Alpha-1-Bedingung bleibt für Early Access und Vollversion unbestätigt.", "Minigunverhalten, Sitze, Zuladung, Widerstandsfähigkeit, Flugverhalten und Preis können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "uh-1y": p("Die normale UH-1Y war in Alpha 1 ein Lufttransporter zu $7,400 ab Pilot 10.", "Die normale UH-1Y war der fortschrittsgebundene Lufttransporter im erfassten Katalog: preislich über dem frei käuflichen MH-6 und knapp unter UH-1Y Miniguns. Pilot 10 war in Alpha 1 lesbar, aber Sitze, Fracht, Flugeigenschaften, Schutz und genaue Unterschiede zur bewaffneten Variante wurden nicht dokumentiert.", "Nutze UH-1Y für geplante Truppbewegung und wiederholte Luftlogistik nach erfüllter beobachteter Pilot-Bedingung. Die Sicherheit des Transports bestimmt Landezonen, nicht eine fehlende Waffenbezeichnung.", ["Lufttransport war die ausdrückliche Alpha-1-Rolle, getrennt von leichten und bewaffneten Hubschrauberklassen.", "Pilot 10 war die einzige lesbare Bedingung der Pilot-Linie in der erfassten Fahrzeuggruppe.", "$7,400 ordneten sie für Familienvergleiche zwischen MH-6 und UH-1Y Miniguns ein."], ["Pilot 10 und $7,400 sind keine bestätigten endgültigen Zugangsregeln.", "Passagiersitze, Frachtkapazität, Flugmodell, Widerstandsfähigkeit und Gegenmaßnahmen wurden nicht erfasst.", "Die Lufttransportrolle beweist keine unbewaffnete oder geschützte Version in späteren Builds."], ["Pilot 10 und $7,400 bleiben für Early Access und Vollversion unbestätigt.", "Sitze, Fracht, Ausstattung, Schutz, Flugverhalten und Gegenmaßnahmen können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "ural-defender-m249": p("Der Ural Defender M249 war in Alpha 1 bewaffnete Logistik zu $6,750 ab Driver 40.", "Der Ural Defender M249 bildete die Spitze der erfassten Ural-Familie: bewaffnete Logistik, Driver 40 und $6,750 in Alpha 1. Er ergänzt das geschützte Defender-Konzept um eine benannte Waffe. Welche Einbußen Fracht, Schutz oder Mobilität durch die M249-Lafette erfahren, belegt kein Eintrag.", "Begleite wertvolle Versorgung mit einer defensiven Bordwaffenrolle. Routensicherheit und Entladeprioritäten haben Vorrang vor ungestützten Gefechtsumwegen.", ["Bewaffnete Logistik war eine einzigartige Rolle der beobachteten Fahrzeuge.", "Die M249-Bezeichnung trennt ihn vom normalen Ural und geschützten Defender.", "Driver 40 und $6,750 machten erfassten Fortschritt und Kaufstufe lesbar."], ["M249-Munition, Feuerwinkel, Schutz, Genauigkeit und Schützenexposition wurden nicht erfasst.", "Frachtkapazität und Abwägung zwischen Logistikraum und Bewaffnung bleiben unbekannt.", "Driver 40 und $6,750 können sich nach Alpha 1 ändern."], ["Driver 40 und $6,750 bleiben für Early Access und Vollversion unbestätigt.", "Waffenverhalten, Fracht, Schutz, Sitze, Mobilität und Betriebskosten können vom aktuellen Early Access oder der Vollversion abweichen."]),
  "ural-defender": p("Der Ural Defender erschien in Alpha 1 als geschützte Logistik zu $6,000 ab Driver 30.", "Der Ural Defender fügte zwischen normalem Lkw und bewaffnetem M249-Modell eine geschützte Logistikstufe ein. Driver 30 und $6,000 waren in Alpha 1 lesbar. Geschützt ist aber keine gemessene Panzerungsangabe; Frachtvolumen, Passagiersitze, Routenleistung und Schutzgewinn gegenüber Ural sind nicht definiert.", "Nutze Ural Defender auf riskanteren Versorgungsrouten, wenn die beobachtete Schutzlogistik wichtiger ist als Urals niedrigerer Kaufpreis oder die Deckungswaffe des bewaffneten Modells.", ["Geschützte Logistik war eine eigene beobachtete Rolle statt allgemeinem Transport.", "$6,000 in Alpha 1 lagen genau zwischen Ural und Ural Defender M249.", "Driver 30 gab der mittleren Ural-Variante eine lesbare Fortschrittsstufe."], ["Panzerungsbewertung, Schadensmodell, Frachtkapazität und Sitzanzahl wurden nicht erfasst.", "Geschützte Logistik bestätigt keinen Schutz gegen jeden Hinterhalt oder Waffentyp.", "Driver 30 und $6,000 bleiben Vorabbeobachtungen."], ["Driver 30 und $6,000 bleiben für Early Access und Vollversion unbestätigt.", "Schutz, Fracht, Sitze, Handhabung, Kraftstoff, Reparatur und Verlustverhalten können vom aktuellen Early Access oder der Vollversion abweichen."]),
  ural: p("Der normale Ural war im Alpha-1-Händler ein Logistik-Lkw zu $5,000 hinter $60,000 Freischaltung.", "Der normale Ural verankerte die spezialisierte Logistikfamilie mit $5,000 Kaufpreis und der größten sichtbaren Geldfreischaltung des erfassten Fahrzeugkatalogs. Separate $60,000 in Alpha 1 bestimmen die Einstiegskosten. Freischaltungsdauer, Fracht, Passagiere, Schutz, Tempo und Versorgungsinteraktionen werden nicht erklärt oder quantifiziert.", "Plane Massentransporte und wiederholte Versorgungsrouten nach Berücksichtigung beider beobachteten Kostenstufen. Begleitung und Routendisziplin gleichen den nicht dokumentierten Schutz aus.", ["Logistik-Lkw war seine ausdrückliche Alpha-1-Rolle, getrennt vom gewöhnlichen Personentransport.", "$5,000 beobachteter Kaufpreis lagen unter beiden Ural-Defender-Varianten.", "$60,000 Freischaltung waren lesbar und machen einen wichtigen zweiten Kostenpunkt sichtbar statt ihn hinter einer Stufe zu verbergen."], ["Saison 1 nennt Driver 3 und $35,000 Freischaltung der Driver-Linie, getrennt vom wiederholten Fahrzeugkauf.", "Frachtkapazität, Beladungsregeln, Versorgungstypen, Passagiersitze und Verlustverhalten wurden nicht erfasst.", "Schutz, Handhabung, Kraftstoff, Reparatur und Geländespezifikationen wurden nicht aufgezeichnet."], ["$5,000 Alpha-1-Fahrzeugpreis bleiben für Early Access ungeprüft; $60,000 Alpha-1-Freischaltung sind historisch.", "Freischaltungsdauer, Frachtregeln, Versorgungsinteraktionen, Schutz, Sitze und Handhabung können vom aktuellen Early Access oder der Vollversion abweichen."]),
  stingray: p("Stingray ist eine bodengestartete Fahrzeugabwehrdrohne aus Beta-Aufnahmen; aktueller Preis, Freischaltung und Schaden sind ungeprüft.", "Stingray ist ein Startgerät mit Steuerung für eine Einwegdrohne gegen Fahrzeuge, kein gewöhnliches fahrbares Fahrzeug. Closed-Beta-Bauaufnahmen zeigen Startrohr und Handsteuerung. Ein September-Clip zeigt Angriffe auf Fahrzeuge und Artillerie; keiner der Belege bestätigt aktuellen Ladenpreis, Freischaltung, Schadenszahl oder garantierte Zerstörung.", "Wähle vor dem Start ein bestätigtes wertvolles Fahrzeug oder stationäre Artillerie. Decke den Bediener und lasse einen Mitspieler den Startort beobachten. Der ältere Flugleitfaden empfiehlt kontrollierte Endkorrekturen statt den gesamten Boost im Anflug zu verbrauchen; prüfe die Steuerung im aktuellen Build erneut.", ["Ein entfernter Fahrzeugangriff kann eine bekannte stationäre Artillerie- oder Spawn-Unterstützungsstellung unter Druck setzen.", "Startgerät und Steuerung sind in den zitierten Beta-Bauaufnahmen direkt sichtbar.", "Ein September-Clip liefert eine neuere Demonstration von Stingray gegen Fahrzeuge."], ["Der Bediener kann beim Steuern offen stehen; starte aus Deckung statt einer offenen FOB.", "Setze Beta-Flugverhalten, Zielsteuerung und Schaden nicht mit dem aktuellen Build gleich.", "Aktueller Kaufpreis, Freischaltbedingung, Einsatzkosten und Schaden sind nicht unabhängig geprüft."], ["Kein aktuelles Ladenbild oder offizieller Hinweis bestätigt Preis, Freischaltung, Einsatzkosten oder Schaden.", "Die Beta-Flugmethode kann von heutiger Handhabung und Zielsteuerung abweichen."]),
};
