function translateFact(source: string): string {
  if (Object.hasOwn(sentences, source)) return sentences[source];
  const match = /^Observed in Alpha 1: ([^:]+): (.+)$/.exec(source);
  if (!match || !Object.hasOwn(labels, match[1])) throw new Error(`Missing de confirmed fact: ${source}`);
  const [, label, value] = match;
  let translation = values[value];
  if (!translation && /^(?:\$[\d,]+|[\d.]+ kg|[\d.]+x[\d.]+mm|\.\d+ (?:Cal|AE|Colt|ACP|Winchester))$/.test(value)) translation = value;
  const gate = /^(Driver|Wardog|Pilot) Level (\d+)$/.exec(value);
  if (!translation && gate) translation = `${values[gate[1]]} ${gate[2]}`;
  const unlock = /^(\$[\d,]+) unlock$/.exec(value);
  if (!translation && unlock) translation = `${unlock[1]} Freischaltung`;
  if (!translation) throw new Error(`Missing de fact value: ${source}`);
  return `In Alpha 1 beobachtet: ${labels[label]}: ${translation}`;
}

